    {id:"motion",route:"lab-motion",no:"02",title:"MOTION LAB",status:"LIVE EXPERIMENT",copy:"Compare timing, easing and motion feel.",preview:'<div class="lab-mini-track"></div><div class="lab-mini-motion"></div>'},
    {id:"spatial",route:"lab-spatial",no:"03",title:"SPATIAL UI LAB",status:"LIVE EXPERIMENT",copy:"Place interfaces across depth and focus.",preview:'<div class="lab-mini-space"><i></i><i></i><i></i></div>'},
    {id:"interaction",route:"lab-interaction",no:"04",title:"INTERACTION PLAYGROUND",status:"LIVE EXPERIMENT",copy:"Test how one object responds to input.",preview:'<div class="lab-mini-magnet">MOVE CLOSER</div>'},
    {id:"material",route:"lab-material",no:"05",title:"MATERIAL LAB",status:"EXPERIMENT",copy:"Shape glass, glow and digital surfaces.",preview:'<div class="lab-mini-material"></div>'},
    {id:"generative",route:"lab-generative",no:"06",title:"GENERATIVE PLAYGROUND",status:"EXPERIMENT",copy:"Guide small systems through force and flow.",preview:'<canvas class="lab-mini-canvas" aria-hidden="true"></canvas>'}
