    $$ (mount,"[data-material='object'] button").forEach(button=>button.addEventListener("click",()=>{state.object=button.dataset.value;update()},{signal:controller.signal}));$$ (mount,"[data-material='preset'] button").forEach(button=>button.addEventListener("click",()=>{Object.assign(state,presets[button.dataset.value]);$$ (mount,"[data-material='preset'] button").forEach(b=>b.classList.toggle("is-active",b===button));sync()},{signal:controller.signal}));
